_RULE = [("Huwag kayong mandaya sa kapwa mo.", "Do not cheat your fellow human beings. (daya, root beginning with d, takes man)"), ("Huwag kayong mandarambong.", "Do not plunder. (dambong takes man)"), ("Kailangan mamitagan kayo sa matatanda.", "You need to show respect for elders. (pitagan, root beginning with p, takes mam)"), ("Ayaw niyang mamaga ang sugat niya, kaya siya nagpagamot.", "He or she did not want the wound to swell, so he or she sought medical help. (maga, root beginning with m, takes mang, and the initial letter is lost)")]
_TM = [["kopya", "mangopya", "to copy someone else’s work"], ["api", "mang-api", "to mistreat someone"], ["huwad", "manghuwad", "to counterfeit"]]
_TN = [["dukot", "mandukot", "to pick someone else’s pocket"], ["loko", "manloko", "to fool someone"], ["raid", "manraid", "to raid, attack or invade an enemy position"], ["silip", "manilip", "to look through a hole"], ["takot", "manakot", "to frighten or scare someone"]]
_TP = [["bato", "mambato", "to throw a rock or stone"], ["bili", "mamili", "to go shopping"], ["pinsala", "maminsala", "to cause damage"], ["pula", "mamula", "to turn red"]]
_CJ = [["tukso", "to tease or joke", "manukso", "nanukso", "nanunukso", "manunukso"], ["sabik", "to be eager or enthusiastic", "manabik", "nanabik", "nananabik", "mananabik"], ["kaliwa", "to cheat on one’s spouse", "mangaliwa", "nangaliwa", "nangangaliwa", "mangangaliwa"]]
L4 = lesson(
    "C25 L1 · Mang verbs: uses, formation and conjugation",
    "Mang, man at mam · Manganak, mamula, mangabayo · Manloko, mandaya, mamili · Nanukso, nananabik, mangangaliwa",
    requires=[],
    cards=[
        card("Mang verbs", "Mang verbs can be both transitive and intransitive. The focus is on the doer. Mang verbs express different things (below). The third use, doing something destructive or harmful deliberately, is discussed in detail in a future lesson about safety and security (Lesson 26); for now the other uses (1, 2, 4 and 5) are discussed.", tables=[table(["No.", "Mang expresses", "Example", "Meaning"], _USES, say=[])]),
        card("Examples from the presentations in Lessons 1 and 2", "The book’s examples with its translations.", examples=passage(_EXM)),
        card("Formation of mang", "Mang is prefixed to verb roots that do not take the mag prefix. The two variants of mang are man and mam. The choice of mang, man or mam depends on the initial letter of the root word. 1. For root words beginning with D, L, R, S or T, man is used. 2. For root words beginning with B or P, mam is used. 3. The prefix mang is used for root words starting with other letters. When the mang prefix is used, the root word normally loses the initial letter or syllable. The book’s example for the mam rule is pitagan.", examples=passage(_RULE)),
        card("Roots with mang", "", tables=[table(["Root word (salitang-ugat)", "Verb (pandiwa)", "Meaning (kahulugan)"], _TM, say=[])]),
        card("Roots with man", "", tables=[table(["Root word", "Verb", "Meaning"], _TN, say=[])]),
        card("Roots with mam", "", tables=[table(["Root word", "Verb", "Meaning"], _TP, say=[])]),
        card("Conjugation of mang verbs", "The conjugation is the same as for mag verbs.", tables=[table(["Root", "Meaning", "Pawatas", "Pangnagdaan", "Pangkasalukuyan", "Panghinaharap"], _CJ, say=[])]),
    ],
    exercises=uniq(
        tr_q([(r[2], r[3]) for r in _USES if r[1] != "(same use)"]) + tr_q([(r[1], r[2]) for r in _TM + _TN + _TP]) + tr_q([(r[2], r[1]) for r in _CJ])
        + tr_q(_RULE) + rev_q(_RULE) + tr_q([(a, b.split(" (")[0]) for a, b in _EXM]) + rev_q([(a, b.split(" (")[0]) for a, b in _EXM])
        + [M(f"What does {r[1]} mean?", r[2], dd([x[2] for x in _TM + _TN + _TP], r[2]), r[2] + ".") for r in _TM + _TN + _TP]
        + [M(f"What is the verb from the root {r[0]}?", r[1], dd([x[1] for x in _TM + _TN + _TP], r[1]), r[1] + ".") for r in _TM + _TN + _TP]
        + [M(f"What is the {t} of {r[2]}?", r[i], dd([x[i] for x in _CJ], r[i]), r[i] + ".") for r in _CJ for i, t in ((3, "past"), (4, "present"), (5, "future"))]
        + [M("Which prefix is used for roots beginning with d, l, r, s or t?", "man", ["mam", "mang", "mag"], "man."), M("Which prefix is used for roots beginning with b or p?", "mam", ["man", "mang", "mag"], "mam."), M("Which prefix is used for other letters?", "mang", ["man", "mam", "mag"], "mang."), M("Do mang verbs focus on the doer?", "yes", ["no, on the object", "no, on the place", "no, on the time"], "doer focus."), M("What does manganak mean?", "to give birth", ["to cheat", "to go horseback riding", "to blush"], "manganak."), M("What does mangabayo mean?", "to go horseback riding", ["to give birth", "to cheat", "to blush"], "mangabayo."), M("What does mamula mean?", "to become red; to blush", ["to give birth", "to cheat", "to go horseback riding"], "mamula."), M("What does mandaya mean?", "to cheat", ["to give birth", "to blush", "to go horseback riding"], "mandaya.")]
        + [F("Huwag kayong ___ sa kapwa mo. (cheat)", "mandaya", ["mamitagan", "manganak"], "mandaya."), F("Kailangan ___ kayo sa matatanda. (show respect)", "mamitagan", ["mandaya", "manloko"], "mamitagan."), F("Ayaw niyang ___ ang sugat niya. (swell)", "mamaga", ["mandaya", "mambato"], "mamaga."), F("Ang past ng manukso ay ___. (teased)", "nanukso", ["nanunukso", "manunukso"], "nanukso.")]
    ),
)

